import{_ as e}from"./chunks/JetBrains-autofix.BJQJdB7G.js";import{_ as r,o as a,c as i,a2 as n}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/JetBrains-fix.Bzr173Uu.png",l="/newx-doc/assets/VSCode%E8%87%AA%E5%8A%A8%E4%BF%9D%E5%AD%98.CT_ZQTvC.png",g=JSON.parse('{"title":"代码格式化","description":"","frontmatter":{},"headers":[],"relativePath":"vben5/format.md","filePath":"vben5/format.md","lastUpdated":null}'),d={name:"vben5/format.md"};function s(p,t,c,h,f,m){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="代码格式化" tabindex="-1">代码格式化 <a class="header-anchor" href="#代码格式化" aria-label="Permalink to &quot;代码格式化&quot;">​</a></h1><p>友情提示</p><p>强烈建议先阅读 Vben Admin 官方文档，了解框架的基础概念和使用方式：</p><ul><li><a href="https://doc.vben.pro/guide/project/standard.html" target="_blank" rel="noreferrer">《规范》</a></li></ul><p>项目的 lint 配置文件位于 <a href="https://github.com/yudaocode/yudao-ui-admin-vben/tree/master/internal/lint-configs" target="_blank" rel="noreferrer">internal/lint-configs</a> 目录下：</p><table tabindex="0"><thead><tr><th>目录</th><th>说明</th></tr></thead><tbody><tr><td><code>eslint-config</code></td><td>ESLint 配置</td></tr><tr><td><code>prettier-config</code></td><td>Prettier 配置</td></tr><tr><td><code>stylelint-config</code></td><td>Stylelint 配置</td></tr><tr><td><code>commitlint-config</code></td><td>Commitlint 配置</td></tr></tbody></table><p>项目内集成了以下几种代码校验工具：</p><ul><li><a href="https://eslint.org/" target="_blank" rel="noreferrer">ESLint</a> ：用于 JavaScript/TypeScript 代码检查</li><li><a href="https://stylelint.io/" target="_blank" rel="noreferrer">Stylelint</a> ：用于 CSS/SCSS 样式检查</li><li><a href="https://prettier.io/" target="_blank" rel="noreferrer">Prettier</a> ：用于代码格式化</li><li><a href="https://commitlint.js.org/" target="_blank" rel="noreferrer">Commitlint</a> ：用于 Git 提交信息规范检查</li></ul><p>我们可以使用 IDE 自带的 Linter 功能，实现代码的格式化（自动检查和修复）。</p><p>友情提示：</p><p>如果你想使用 Prettier 插件，可参考 <a href="https://vue3/format" target="_blank" rel="noreferrer">《代码格式化（Prettier）》</a> 文档。</p><h2 id="_1-jetbrains-端" tabindex="-1">1. JetBrains 端 <a class="header-anchor" href="#_1-jetbrains-端" aria-label="Permalink to &quot;1. JetBrains 端&quot;">​</a></h2><p>参考 <a href="https://www.jetbrains.com/help/idea/linters.html" target="_blank" rel="noreferrer">《JetBrains 官方文档》</a> 操作即可。</p><hr><p>① 【手动修复】右键文件，选择 <code>Fix ESLint Problems</code> 即可。如下图所示：</p><p><img src="'+o+'" alt="JetBrains 端 ESLint 自动修复"></p><p>② 【自动修复】可在 JetBrains 设置界面的 ESLint 选项中，勾选上 <code>Run eslint --fix on save</code> 选项，如下图所示：</p><p><img src="'+e+'" alt="JetBrains 端 ESLint 自动修复 - 设置"></p><p>之后，保存页面，页面代码自动格式化。</p><h2 id="_2-vs-code-端" tabindex="-1">2. VS Code 端 <a class="header-anchor" href="#_2-vs-code-端" aria-label="Permalink to &quot;2. VS Code 端&quot;">​</a></h2><p>参考 <a href="https://code.visualstudio.com/docs/languages/javascript#_linters" target="_blank" rel="noreferrer">《VS Code 官方文档》</a> 操作即可。</p><hr><p>【自动修复】打开 VS Code 配置，搜索 save 后，勾选上 <code>Format On Save</code> 选项。如下图所示：</p><p><img src="'+l+'" alt="VS Code 端自动格式化 - 设置"></p><p>之后，保存页面，页面代码自动格式化。</p>',25)])])}const u=r(d,[["render",s]]);export{g as __pageData,u as default};
